export const hours = (from: string, to: string) => (Date.parse(to) - Date.parse(from)) / 3_600_000;

export const median = (xs: number[]) => {
  const s = xs.toSorted((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};

// nearest rank: the smallest value that at least q of the values are at or under
export const quantile = (xs: number[], q: number) => xs.toSorted((a, b) => a - b)[Math.ceil(q * xs.length) - 1];
