import { hours, median, quantile } from "./stats.ts";

type Author = { login: string; __typename: "User" | "Bot" };
type Event =
  | { __typename: "ReadyForReviewEvent"; createdAt: string }
  | { __typename: "PullRequestReview"; createdAt: string; author: Author };
export type PullRequest = { number: number; createdAt: string; author: Author; requestedBy?: string; timeline: Event[] };
export type Point = [name: string, labels: Record<string, string>, value: number, timestamp: number];

/** Ready for review (or opened, if never a draft) to the first review by another person. */
export const reviewWaitHours = (pr: PullRequest): number | undefined => {
  const ready = pr.timeline.find((e) => e.__typename === "ReadyForReviewEvent")?.createdAt ?? pr.createdAt;
  const first = pr.timeline.find((e) => e.__typename === "PullRequestReview"
    && e.author.__typename === "User" && e.author.login !== pr.author.login);
  return first ? hours(ready, first.createdAt) : undefined;
};

const cohortOf = (pr: PullRequest) => (pr.author.__typename === "Bot" ? "agent" : "human");

/** One week of PRs in, a few numbers per team and cohort out. Never a login. */
export function* weeklyPoints(prs: PullRequest[], teamOf: (pr: PullRequest) => string, weekTs: number): Generator<Point> {
  const groups = Map.groupBy(prs, (pr) => `${teamOf(pr)}|${cohortOf(pr)}`);
  for (const [key, items] of groups) {
    const [team, cohort] = key.split("|");
    const waits = items.map(reviewWaitHours).filter((w) => w !== undefined);
    yield ["delivery_reviewed_prs", { team, cohort }, waits.length, weekTs];
    if (waits.length < 2) continue;
    yield ["delivery_review_wait_hours", { team, cohort, q: "p50" }, median(waits), weekTs];
    yield ["delivery_review_wait_hours", { team, cohort, q: "p85" }, quantile(waits, 0.85), weekTs];
  }
}
